import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"Protos & Codegen","description":"","frontmatter":{},"headers":[],"relativePath":"development/protos.md","filePath":"development/protos.md","lastUpdated":1780254295000}'),i={name:"development/protos.md"};function d(s,e,c,l,n,p){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="protos-codegen" tabindex="-1">Protos &amp; Codegen <a class="header-anchor" href="#protos-codegen" aria-label="Permalink to &quot;Protos &amp; Codegen&quot;">​</a></h1><p>Soma defines its peer-facing (libp2p) message schemas in <code>proto/</code> using Protocol Buffers. These are Rust-only wire formats; the desktop renderer no longer uses them for IPC (it talks to the Tauri host over commands — see below).</p><h2 id="where-the-proto-files-live" tabindex="-1">Where the <code>.proto</code> files live <a class="header-anchor" href="#where-the-proto-files-live" aria-label="Permalink to &quot;Where the `.proto` files live&quot;">​</a></h2><ul><li>Daemon peer messages: <code>proto/daemon/v1/daemon.proto</code></li><li>Agent messages: <code>proto/agent/v1/agent.proto</code></li><li>Membership/capabilities: <code>proto/space/v1/membership.proto</code></li></ul><h2 id="how-rust-bindings-are-generated" tabindex="-1">How Rust bindings are generated <a class="header-anchor" href="#how-rust-bindings-are-generated" aria-label="Permalink to &quot;How Rust bindings are generated&quot;">​</a></h2><p>Rust types and gRPC service stubs are built at compile time by the <code>soma-proto-build</code> crate:</p><ul><li>Crate: <code>backend/crates/proto-build</code></li><li>Build script: <code>backend/crates/proto-build/build.rs</code></li><li>Modules re-exported from: <code>backend/crates/proto-build/src/lib.rs</code></li></ul><p><code>build.rs</code> uses <code>tonic_prost_build</code> to compile the <code>.proto</code> files into the crate’s <code>OUT_DIR</code>, and <code>tonic::include_proto!</code> pulls them into Rust modules.</p><p>The build script defaults to the workspace <code>proto/</code> directory, but it also accepts <code>SOMA_PROTO_ROOT</code> as an override. That keeps local builds working today while making it possible to point the backend at an external contracts checkout later.</p><p>Practical implications:</p><ul><li>Editing a <code>.proto</code> file will trigger rebuilds automatically (<code>cargo:rerun-if-changed=...</code>).</li><li>There is no checked-in generated Rust code; it is produced by Cargo builds.</li></ul><h2 id="buf-configuration" tabindex="-1">Buf configuration <a class="header-anchor" href="#buf-configuration" aria-label="Permalink to &quot;Buf configuration&quot;">​</a></h2><p>The repo includes Buf config files under <code>proto/</code>:</p><ul><li><code>proto/buf.yaml</code></li><li><code>proto/buf.gen.yaml</code></li></ul><p>They currently act as scaffolding for linting/managed-mode workflows; Rust codegen is performed by Cargo (<code>tonic_prost_build</code>) rather than a Buf plugin.</p><p>Buf is also the right place to keep future cross-repo lint/breaking checks once contracts move out of this monorepo.</p><h2 id="how-typescript-types-reach-the-renderer" tabindex="-1">How TypeScript types reach the renderer <a class="header-anchor" href="#how-typescript-types-reach-the-renderer" aria-label="Permalink to &quot;How TypeScript types reach the renderer&quot;">​</a></h2><p>The <code>.proto</code> files are <strong>Rust-only</strong> — they describe the libp2p wire formats. There is no longer a TypeScript proto-codegen package: <code>desktop/desktop-proto</code> (<code>@soma/proto</code>) was removed with the Electron app.</p><p>The renderer no longer speaks gRPC. The Tauri host exposes its behaviour as <code>#[tauri::command]</code>s, and <code>tauri-specta</code> walks that command graph to emit TypeScript wire types into <code>desktop/desktop-sdk/src/bindings/</code>. The renderer consumes them through the typed <code>@soma/sdk</code> facade — never by hand-writing wire types and never from generated proto stubs.</p><h2 id="quick-local-checks" tabindex="-1">Quick local checks <a class="header-anchor" href="#quick-local-checks" aria-label="Permalink to &quot;Quick local checks&quot;">​</a></h2><ul><li>Compile Rust bindings: <code>cargo build -p soma-proto-build</code></li><li>Compile a Rust crate that uses the protos: <code>cargo build -p somad</code></li><li>Regenerate the <code>@soma/sdk</code> bindings: build the Tauri host (the specta export runs as part of the <code>desktop-commands</code> build); the output lands in <code>desktop/desktop-sdk/src/bindings/</code>.</li></ul>',21)])])}const m=o(i,[["render",d]]);export{u as __pageData,m as default};
